import{_ as a,a as o,b as s}from"./chunks/30.DJULZAiv.js";import{_ as r,o as l,c as i,a0 as n}from"./chunks/framework.DRjqbEpm.js";const k=JSON.parse('{"title":"📦 備份與還原中心","description":"","frontmatter":{},"headers":[],"relativePath":"guide/backup.md","filePath":"guide/backup.md"}'),e={name:"guide/backup.md"};function d(c,t,p,g,h,u){return l(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="📦-備份與還原中心" tabindex="-1">📦 備份與還原中心 <a class="header-anchor" href="#📦-備份與還原中心" aria-label="Permalink to &quot;📦 備份與還原中心&quot;">​</a></h1><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>V-Train 採用「零伺服器架構」，您的所有資料只存在<strong>您的電腦</strong>裡，我們的伺服器完全不保有任何副本。<br> 這保護了您的隱私，但也代表：<strong>定期備份是您的責任！</strong> 請養成定期備份的好習慣！</p></div><hr><h2 id="🔒-為什麼要備份" tabindex="-1">🔒 為什麼要備份？ <a class="header-anchor" href="#🔒-為什麼要備份" aria-label="Permalink to &quot;🔒 為什麼要備份？&quot;">​</a></h2><p>V-Train 使用瀏覽器的 <strong>IndexedDB</strong> 與 <strong>chrome.storage.local</strong> 來儲存您的所有資料。這些資料存放在您本地的瀏覽器中，包含：</p><table tabindex="0"><thead><tr><th>資料種類</th><th>說明</th></tr></thead><tbody><tr><td>📊 觀看進度紀錄</td><td>所有影片的播放進度百分比</td></tr><tr><td>⚙️ 系統設定</td><td>進度條顏色、語言、開關狀態等</td></tr><tr><td>🗺️ 訓練規則</td><td>您親手訓練的所有影音網站規則</td></tr><tr><td>❤️ 書籤收藏</td><td>您儲存的影片書籤與資料夾結構</td></tr><tr><td>⭐ 評分紀錄</td><td>影片的喜歡/不喜歡評分</td></tr><tr><td>🖼️ 自訂封面</td><td>您用截圖功能拍攝的高畫質縮圖</td></tr></tbody></table><p>以下情況<strong>將導致所有資料永久消失</strong>（無法復原）：</p><div class="danger custom-block"><p class="custom-block-title">⚠️ 資料遺失的常見原因</p><ul><li>🗑️ <strong>移除 V-Train 擴充功能</strong></li><li>🔄 <strong>重置瀏覽器設定</strong>（清除應用程式資料）</li><li>💻 <strong>換電腦</strong>或<strong>重灌系統</strong></li><li>🧹 <strong>清除瀏覽器快取與 Cookies</strong>（部分清除選項包含 IndexedDB）</li><li>⚠️ <strong>Chrome 的自動磁碟空間清理</strong>（少見但存在）</li></ul></div><hr><h2 id="🚀-如何開始備份" tabindex="-1">🚀 如何開始備份 <a class="header-anchor" href="#🚀-如何開始備份" aria-label="Permalink to &quot;🚀 如何開始備份&quot;">​</a></h2><p>備份功能在<strong>控制面板</strong>的上方區域。</p><blockquote><p><img src="'+a+'" alt="備份與還原按鈕"></p></blockquote><p>點擊 <strong>「Export Full Backup (incl. Rules)」</strong> 按鈕，系統會跳出一個選項視窗讓您選擇要匯出的內容。</p><hr><h2 id="⬆️-匯出資料-備份" tabindex="-1">⬆️ 匯出資料（備份） <a class="header-anchor" href="#⬆️-匯出資料-備份" aria-label="Permalink to &quot;⬆️ 匯出資料（備份）&quot;">​</a></h2><h3 id="選擇備份內容" tabindex="-1">選擇備份內容 <a class="header-anchor" href="#選擇備份內容" aria-label="Permalink to &quot;選擇備份內容&quot;">​</a></h3><p>V-Train 提供兩種備份選項，您可以<strong>同時勾選</strong>或<strong>分開備份</strong>：</p><div class="info custom-block"><p class="custom-block-title">📋 核心資料 (Core Data)</p><p>包含：觀看進度紀錄、訓練規則、書籤清單、資料夾結構、評分紀錄、系統設定。<br><strong>檔案大小通常很小</strong>（幾百 KB 到幾 MB），建議在訓練完新網站、或設定告一段落時備份一次，避免心血白費。</p></div><div class="info custom-block"><p class="custom-block-title">🖼️ 截圖封面圖片 (Images)</p><p>包含：您用截圖功能拍攝的所有自訂封面圖片，儲存格式為壓縮後的 WebP 圖片。<br><strong>警告</strong>：如果您有大量截圖，這個檔案可能非常大，備份時間也會較長。</p></div><h3 id="備份流程說明" tabindex="-1">備份流程說明 <a class="header-anchor" href="#備份流程說明" aria-label="Permalink to &quot;備份流程說明&quot;">​</a></h3><p>點擊匯出後，系統會開啟一個<strong>備份進度頁面</strong>，全程自動執行，您只需等待：</p><blockquote><p><img src="'+o+`" alt="備份進度頁面"></p></blockquote><ol><li><strong>初始化</strong> (Initializing)：準備讀取資料庫</li><li><strong>讀取核心資料</strong> (Fetching Core Data)：讀取觀看紀錄、書籤、設定等（進度 10% → 30%）</li><li><strong>打包圖片</strong> (Packaging Images)：若有截圖，分塊打包（進度 30% → 85%）</li><li><strong>壓縮 ZIP</strong> (Compressing ZIP)：使用 DEFLATE 演算法壓縮（壓縮等級 6），進度 85% → 100%</li><li><strong>下載完成</strong>：自動觸發下載，檔案名格式為 <code>VTrain_Backup_YYYY-MM-DD.zip</code></li></ol><div class="tip custom-block"><p class="custom-block-title">💡 超大量截圖也不怕！</p><p>如果您是超級收藏家，有數千張截圖封面，V-Train 有內建「<strong>智能分塊打包技術</strong>」！<br> 系統會自動將圖片切成每批 <strong>1000 張</strong>一個 JSON 檔案（<code>images_part_1.json</code>、<code>images_part_2.json</code>...），確保備份過程順暢不當機。</p></div><h3 id="備份檔案結構" tabindex="-1">備份檔案結構 <a class="header-anchor" href="#備份檔案結構" aria-label="Permalink to &quot;備份檔案結構&quot;">​</a></h3><p>解壓 <code>VTrain_Backup_YYYY-MM-DD.zip</code> 後，您會看到：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VTrain_Backup_2025-01-01.zip</span></span>
<span class="line"><span>├── core_data.json          # 核心資料（紀錄、規則、書籤、設定）</span></span>
<span class="line"><span>├── images_part_1.json      # 截圖封面第1批（若存在）</span></span>
<span class="line"><span>├── images_part_2.json      # 截圖封面第2批（若存在）</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">請妥善保存備份檔</p><p>建議將備份 ZIP 同時儲存到：</p><ul><li>☁️ 雲端硬碟（Google Drive、OneDrive 等）</li><li>💾 外接硬碟</li><li>📱 不同裝置</li></ul></div><hr><h2 id="⬇️-匯入資料-還原" tabindex="-1">⬇️ 匯入資料（還原） <a class="header-anchor" href="#⬇️-匯入資料-還原" aria-label="Permalink to &quot;⬇️ 匯入資料（還原）&quot;">​</a></h2><h3 id="何時需要還原" tabindex="-1">何時需要還原？ <a class="header-anchor" href="#何時需要還原" aria-label="Permalink to &quot;何時需要還原？&quot;">​</a></h3><ul><li>換了新電腦，想把舊資料帶過來</li><li>不小心清除了瀏覽器資料，想從備份恢復</li><li>在多台電腦之間同步您的訓練規則與書籤</li></ul><h3 id="還原步驟" tabindex="-1">還原步驟 <a class="header-anchor" href="#還原步驟" aria-label="Permalink to &quot;還原步驟&quot;">​</a></h3><ol><li>點擊控制面板上方的 <strong>「Import Full Backup (incl. Rules)」</strong> 按鈕</li><li>系統跳轉到<strong>還原中心頁面</strong></li><li>點擊 <strong>「📂 Select Backup File（選擇備份檔案）」</strong> 按鈕</li><li>從您的電腦選擇之前下載的 <strong><code>.zip</code> 備份檔案</strong></li></ol><blockquote><p><img src="`+s+'" alt="還原中心頁面"></p></blockquote><ol start="5"><li>系統開始自動讀取並還原，進度條會即時更新</li><li>還原完成後，點擊「Close Tab（關閉頁籤）」即可</li></ol><div class="tip custom-block"><p class="custom-block-title">💡 還原後需要重新整理</p><p>還原完成後，建議<strong>重新整理</strong>您正在瀏覽的影片網站，讓 V-Train 重新載入最新的規則與資料。</p></div><h3 id="還原順序建議" tabindex="-1">還原順序建議 <a class="header-anchor" href="#還原順序建議" aria-label="Permalink to &quot;還原順序建議&quot;">​</a></h3><p>如果您有分開備份核心資料和圖片，建議：</p><ol><li><strong>先還原</strong> <code>core_data.json</code>（選擇含核心資料的 ZIP）</li><li><strong>再還原</strong>圖片（選擇含 <code>images_part_*.json</code> 的 ZIP）</li></ol><p>還原程式會自動識別 ZIP 裡面的檔案類型，您不需要手動分辨。</p><hr><h2 id="🔄-跨裝置同步設定" tabindex="-1">🔄 跨裝置同步設定 <a class="header-anchor" href="#🔄-跨裝置同步設定" aria-label="Permalink to &quot;🔄 跨裝置同步設定&quot;">​</a></h2><p>V-Train 目前沒有自動雲端同步功能（為了絕對隱私）。如果您要在多台電腦上使用相同的設定：</p><ol><li>在<strong>電腦 A</strong> 匯出備份 ZIP</li><li>把 ZIP 傳送到<strong>電腦 B</strong>（透過雲端硬碟、隨身碟等）</li><li>在<strong>電腦 B</strong> 的 V-Train 中，使用匯入功能還原</li></ol><div class="info custom-block"><p class="custom-block-title">規則分享更方便的方法</p><p>如果只是想分享<strong>訓練規則</strong>給朋友，不需要完整備份！<br> 直接去「控制面板」→「已訓練網站」，複製單個規則的 <strong>VT-RULE-Z... 序號</strong>給朋友就好，比傳 ZIP 更輕鬆！</p></div><hr><h2 id="📋-備份建議排程" tabindex="-1">📋 備份建議排程 <a class="header-anchor" href="#📋-備份建議排程" aria-label="Permalink to &quot;📋 備份建議排程&quot;">​</a></h2><table tabindex="0"><thead><tr><th>使用習慣</th><th>建議備份頻率</th></tr></thead><tbody><tr><td>偶爾使用</td><td>每月一次</td></tr><tr><td>一般使用</td><td>每兩週一次</td></tr><tr><td>重度使用（大量截圖、書籤）</td><td>每週一次</td></tr><tr><td>剛訓練完新網站</td><td>立即備份！</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">最重要的一件事</p><p><strong>在升級 Chrome 或系統更新前，請先備份一次！</strong> 雖然這種情況很少見，但系統更新有時候會清除擴充功能的本地儲存資料。</p></div>',50)])])}const _=r(e,[["render",d]]);export{k as __pageData,_ as default};
